def decompress_stdin(data: bytes, fmt: str|None=None, output_dir: str|None=None, here: bool=False) -> tuple[str,int]:
    """Decode compressed bytes from stdin into the conventional ouch-output file."""
    import io
    kind=(fmt or '').lower().lstrip('.')
    if not kind:
        if data.startswith(b'\x1f\x8b'): kind='gz'
        elif data.startswith(b'BZh'): kind='bz2'
        elif data.startswith(b'\xfd7zXZ\x00'): kind='xz'
        elif data.startswith(b'PK\x03\x04'): kind='zip'
        else: raise ValueError('Cannot decompress files\n - Files with missing extensions: "-"')
    target=Path(output_dir or '.') / 'ouch-output'
    target.parent.mkdir(parents=True,exist_ok=True)
    if kind in ('gz','gzip'): decoded=gzip.decompress(data)
    elif kind in ('bz','bz2'): decoded=bz2.decompress(data)
    elif kind in ('xz','lzma'): decoded=lzma.decompress(data)
    elif kind in ('zip','cbz','epub'):
        root=Path(output_dir or '.') if not here else Path('.')
        root.mkdir(parents=True,exist_ok=True)
        with zipfile.ZipFile(io.BytesIO(data)) as zf: _extract_zip(zf,root)
        return 'STDIN archive',0
    elif kind.startswith('tar'):
        raw=data
        if kind.endswith('.gz') or kind=='tgz': raw=gzip.decompress(raw)
        elif kind.endswith(('.bz','.bz2')): raw=bz2.decompress(raw)
        elif kind.endswith(('.xz','.lzma')): raw=lzma.decompress(raw)
        root=Path(output_dir or 'ouch-output') if not here else Path('.')
        root.mkdir(parents=True,exist_ok=True)
        with tarfile.open(fileobj=io.BytesIO(raw),mode='r:*') as tf: _extract_tar(tf,root)
        return 'STDIN archive',0
    else: raise ValueError('unsupported format: '+kind)
    target.write_bytes(decoded)
    return str(target),len(decoded)
