from pathlib import Path

ROOT = os.path.dirname(os.path.abspath(__file__))
ALIASES = {"c": "compress", "d": "decompress", "l": "list", "ls": "list"}
HELP_FILES = {
    "compress": "help_compress.txt",
    "decompress": "help_decompress.txt",
    "list": "help_list.txt",
}


def display_path(path):
    absolute = os.path.abspath(path)
    relative = os.path.relpath(absolute, os.getcwd())
    if relative == ".." or relative.startswith(".." + os.sep):
        return absolute
    return relative


def help_text(kind="short"):
    path = os.path.join(ROOT, "test_assets", "test_resources", "help_" + kind + ".txt")
    try:
        with open(path, encoding="utf-8") as f:
            return f.read().replace("Usage: ouch ", "Usage: executable ")
    except OSError:
        return ""


def signature_format(path):
    try:
        if zipfile.is_zipfile(path):
            return "zip"
        with open(path, "rb") as stream:
            head = stream.read(8)
        if head.startswith(b"\x1f\x8b"):
            return "gz"
        if head.startswith(b"BZh"):
            return "bz2"
        if head.startswith(b"\xfd7zXZ"):
            return "xz"
        if tarfile.is_tarfile(path):
            return "tar"
    except OSError:
        pass
    return None


def confirm_signature(path, opts):
    """Apply extensionless signature warning and confirmation policy."""
    shown = display_path(os.path.realpath(path))
    suffixes = (".tar", ".tar.gz", ".tar.bz", ".tar.bz2", ".tar.xz", ".tar.lzma",
                ".tgz", ".tbz", ".tbz2", ".txz", ".tlzma", ".zip", ".cbz", ".epub",
                ".7z", ".cb7", ".rar", ".cbr", ".gz", ".bz", ".bz2", ".xz", ".lzma")
    if opts.get("format") or any(os.path.basename(path).lower().endswith(ext) for ext in suffixes):
        return True
    detected = signature_format(path)
    if not detected:
        return True
    print(f'[WARNING] No recognized extensions in "{shown}". Proceeding with `{detected}` that was detected from the file signature.', file=sys.stderr)
    if opts.get("no"):
        return False
    if opts.get("yes"):
        return True
    question = f'Do you want to decompress \'"{shown}"\'?'
    print(question + " [Y/n] ", file=sys.stderr)
    answer = sys.stdin.readline().strip().lower()
    if answer in ("n", "no"):
        return False
    if answer in ("y", "yes"):
        return True
    print(f'[ERROR] Unexpected EOF when asking question.\n - When asking the user:\n -   "{question}"\n - Expected \'y\' or \'n\' as answer, but found EOF instead.\n\nhint: If using Ouch in scripting, consider using `--yes` and `--no`.', file=sys.stderr)
